/* Service worker for the espace adhérent.
 *
 * Hand-written rather than generated by a PWA module: all it needs to do is
 * receive pushes and open the app. The site is ssr:false with no nitro config,
 * so a full offline/precache setup would be a lot of machinery for no benefit —
 * and a stale precache would be actively harmful for a page whose whole point
 * is showing an up-to-date balance.
 *
 * Deliberately no `fetch` handler: without one the browser goes straight to the
 * network, which is exactly what we want.
 */

// Take over immediately on install/update so a member who reinstalls the page
// doesn't keep an old worker around.
self.addEventListener("install", () => self.skipWaiting());
self.addEventListener("activate", (event) => event.waitUntil(self.clients.claim()));

self.addEventListener("push", (event) => {
  let payload = {};
  try {
    payload = event.data ? event.data.json() : {};
  } catch {
    // Malformed payload — still show something rather than swallowing it,
    // otherwise the member gets a silent "background sync" notification from
    // the browser itself, which looks broken.
    payload = {};
  }

  const title = payload.title || "Augny Badminton";
  const options = {
    body: payload.body || "",
    icon: "/icons/icon-192.png",
    badge: "/icons/badge-72.png",
    // Collapse repeat reminders so a member who ignores three of them sees one
    // notification, not a stack.
    tag: payload.tag || "augny-generic",
    renotify: Boolean(payload.renotify),
    data: { url: payload.url || "/mon-compte" },
  };

  event.waitUntil(self.registration.showNotification(title, options));
});

self.addEventListener("notificationclick", (event) => {
  event.notification.close();
  const target = (event.notification.data && event.notification.data.url) || "/mon-compte";

  event.waitUntil(
    self.clients.matchAll({ type: "window", includeUncontrolled: true }).then((clientList) => {
      // Focus an existing tab if the app is already open, rather than piling up
      // duplicates every time a reminder is tapped.
      for (const client of clientList) {
        if (client.url.includes(target) && "focus" in client) return client.focus();
      }
      if (self.clients.openWindow) return self.clients.openWindow(target);
      return undefined;
    }),
  );
});
